// Una lista de 1.000.000 de números pares ordenados: 0, 2, 4, ... 1.999.998
const n = 1_000_000;
const a = Array.from({ length: n }, (_, i) => 2 * i);

// Búsqueda lineal: mira de a uno. Devuelve la posición (o -1) y cuántas comparaciones hizo.
function lineal(a, x) {
  let pasos = 0;
  for (let i = 0; i < a.length; i++) {
    pasos++;
    if (a[i] === x) return { pos: i, pasos };
  }
  return { pos: -1, pasos };
}

// Búsqueda binaria. Invariante: si x está en el arreglo, está entre a[lo] y a[hi].
function binaria(a, x) {
  let lo = 0, hi = a.length - 1, pasos = 0;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    pasos++;
    if (a[mid] === x) return { pos: mid, pasos };
    if (a[mid] < x) lo = mid + 1;   // descarto todo lo de a[lo..mid]
    else hi = mid - 1;              // descarto todo lo de a[mid..hi]
  }
  return { pos: -1, pasos };
}

const buscados = [
  ["el primero", 0],
  ["uno del medio", 1_000_000],
  ["el último", 1_999_998],
  ["uno que no está (impar)", 777_777],
];
for (const [nombre, x] of buscados) {
  const l = lineal(a, x), b = binaria(a, x);
  console.log(`${nombre.padEnd(26)} lineal: ${String(l.pasos).padStart(7)} pasos | binaria: ${String(b.pasos).padStart(2)} pasos | misma posición: ${l.pos === b.pos}`);
}

// El peor caso de la binaria para n elementos es floor(log2(n)) + 1 comparaciones
for (const m of [1_000, 1_000_000, 1_000_000_000]) {
  console.log(`n = ${m.toLocaleString("es-AR")}: peor caso binaria = ${Math.floor(Math.log2(m)) + 1} comparaciones`);
}

// Simulamos el «int» de 32 bits con signo de Java o C: (x | 0) recorta a 32 bits
const MAX_INT = 2 ** 31 - 1;
console.log("el int más grande:", MAX_INT);
const lo = 1_500_000_000, hi = 2_000_000_000;       // dos posiciones válidas en un arreglo de 2 mil millones
console.log("lo + hi (matemática):", lo + hi);
console.log("lo + hi en int de 32 bits:", (lo + hi) | 0);
console.log("(lo + hi) / 2 en int:", Math.trunc(((lo + hi) | 0) / 2), " <- posición negativa");
console.log("lo + (hi - lo) / 2 en int:", lo + Math.trunc((hi - lo) / 2), " <- correcto");
console.log("(lo + hi) >>> 1 :", (lo + hi) >>> 1, " <- correcto (suma sin signo)");

// Variantes con intervalo [lo, hi): lo se incluye, hi no.
// Invariante: todo lo que está antes de lo es MENOR que x, y todo lo que está desde hi es MAYOR O IGUAL.
function primeraPosicion(a, x) {      // primer índice con a[i] >= x (a.length si no hay)
  let lo = 0, hi = a.length;
  while (lo < hi) {
    const mid = lo + ((hi - lo) >> 1);
    if (a[mid] < x) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}
function despuesDelUltimo(a, x) {     // primer índice con a[i] > x
  let lo = 0, hi = a.length;
  while (lo < hi) {
    const mid = lo + ((hi - lo) >> 1);
    if (a[mid] <= x) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

// Ejemplo: códigos de zona de entrega de un día, ordenados, con repetidos
const zonas = [1, 1, 3, 3, 3, 3, 7, 9, 9, 12];
for (const z of [3, 9, 5, 0, 20]) {
  const p = primeraPosicion(zonas, z), q = despuesDelUltimo(zonas, z);
  console.log(`zona ${z}: primera posición ${p}, después de la última ${q}, cantidad ${q - p}`);
}

// Comprobación contra fuerza bruta en TODOS los arreglos ordenados de largo 0 a 6 con valores 0..3
let casos = 0, fallas = 0;
function recorrer(a, largo) {
  if (a.length === largo) {
    for (let x = -1; x <= 4; x++) {
      casos++;
      const p = a.findIndex(v => v >= x), q = a.findIndex(v => v > x);
      const esperadoP = p === -1 ? a.length : p, esperadoQ = q === -1 ? a.length : q;
      if (primeraPosicion(a, x) !== esperadoP || despuesDelUltimo(a, x) !== esperadoQ) fallas++;
    }
    return;
  }
  const desde = a.length ? a[a.length - 1] : 0;
  for (let v = desde; v <= 3; v++) recorrer([...a, v], largo);
}
for (let largo = 0; largo <= 6; largo++) recorrer([], largo);
console.log(`${casos} casos comprobados, ${fallas} fallas`);
